import * as C from './credit.js';
import * as O from './objectives.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const metrics=[['points','Points'],['offensive_rebounds','Offensive rebounds'],['paint_touches','Paint touches'],['transition_points','Transition points'],['turnovers','Turnovers'],['deflections','Deflections'],['fouls','Fouls'],['custom','Custom category']];
export function objectiveCards(game,editable=false,compact=false){
 const rows=O.rows(game);if(!rows.length)return '<p class="field-note">No game-plan objectives. Add only the goals you want to see tonight.</p>';
 return '<div class="objective-card-grid'+(compact?' compact-objectives':'')+'">'+rows.map(o=>{
 const who=({both_teams:'Us vs. opponent',our_team:'Our team',opponent_team:'Opponent team',our_player:'Our player',opponent_player:'Opponent player'})[o.subject],player=o.subject.indexOf('_player')>0?' · '+C.playerLabel(game,o.subject==='opponent_player'?'opponent':'us',o.jersey)+(o.playerLabel&&!((o.subject==='opponent_player'?game.opponentRoster:game.ourRoster)||[]).some(p=>p.jersey===o.jersey)?' · '+o.playerLabel:''):'',goal=o.goalType==='track'?'Just tracking':o.goalType==='comparison'?'Win by '+o.target+' · '+(o.direction==='lower'?'fewer':'more')+' is better':(o.goalType==='minimum'?'At least ':'At most ')+o.target+(o.unit==='percentage'?'%':''),value=o.goalType==='comparison'?(o.unit==='percentage'?(o.ourAttempts?o.our+'%':'—')+' vs. '+(o.opponentAttempts?o.opponent+'%':'—'):o.our+' vs. '+o.opponent):o.measured?o.value+(o.unit==='percentage'?'%':''):'—';
 const controls=editable&&!o.automatic?['our','opponent'].filter(s=>o.subject==='both_teams'||s===(o.subject.indexOf('opponent')===0?'opponent':'our')).map(side=>`<div class="objective-manual"><small>${side==='our'?'Us':'Opponent'}</small>${o.unit==='percentage'?['made','miss'].map(kind=>`<button data-action="objective-tap" data-id="${esc(o.id)}" data-side="${side}" data-kind="${kind}" data-amount="1">${kind==='made'?'Made':'Missed'}</button>`).join(''):(o.unit==='points'?[1,2,3]:[1]).map(n=>`<button data-action="objective-tap" data-id="${esc(o.id)}" data-side="${side}" data-kind="count" data-amount="${n}">+${n}</button>`).join('')}</div>`).join(''):'';
 if(compact)return `<article class="objective-goal-card"><small>${esc(who+player)}</small><div class="compact-goal-heading"><h3>${esc(o.label)}</h3><strong>${esc(value)}</strong></div><p>${esc(goal)} · <b>${esc(o.status)}</b>${o.automatic?' · Auto':''}</p>${controls}</article>`;
 return `<article class="objective-goal-card"><small>${esc(who+player)}</small><h3>${esc(o.label)}</h3><strong>${esc(value)}</strong><p>${esc(goal)} · <b>${esc(o.status)}</b></p>${o.unit==='percentage'?`<small>Recorded attempts: ${o.subject==='both_teams'?o.ourMade+'/'+o.ourAttempts+' us · '+o.opponentMade+'/'+o.opponentAttempts+' opponent':o.subject.indexOf('opponent')===0?o.opponentMade+'/'+o.opponentAttempts:o.ourMade+'/'+o.ourAttempts}</small>`:''}<p class="field-note ${compact?'compact-source':''}">${compact?(o.automatic?'Automatic':'Tap to count'):o.automatic?'Automatic · completed possessions only. Player goals require credited events. Score-only adjustments excluded.':'Manual · only your objective taps count. These taps do not change the game score.'}</p>${controls}${editable&&!compact?`<button class="quiet" data-action="objective-archive" data-id="${esc(o.id)}">Hide objective</button>`:''}</article>`;
 }).join('')+'</div>';
}
export function objectiveBuilder(game){return `<details class="objective-builder" open><summary>Add an optional objective</summary><form id="objectiveForm"><div class="form-grid"><label>What to track<select id="objMetric">${metrics.map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select></label><label id="objCustomWrap" hidden>Custom category<input id="objCustom" maxlength="60"></label><label>Game-plan goal<select id="objGoal"><option value="track">Just track it</option><option value="minimum">Reach at least</option><option value="maximum">Stay under</option><option value="comparison">Win the battle · team comparison</option></select></label><label id="objWhoWrap">Who<select id="objWho"><option value="our_team">Our team</option><option value="opponent_team">Opponent team</option><option value="our_player">Our player</option><option value="opponent_player">Opponent player</option></select></label><div id="objPlayerWrap" hidden><label id="objRosterWrap">Player<select id="objRosterSelect"></select></label><p id="objRosterEmpty" class="field-note" hidden>No roster loaded for this team. Enter a jersey number, or load the roster in a new game preparation.</p><label id="objManualWrap" hidden>Player jersey #<input id="objPlayer" maxlength="3" inputmode="numeric" pattern="[0-9]{1,3}" placeholder="12"></label></div><label id="objTargetWrap" hidden>Target / margin<input id="objTarget" type="number" min="0" max="9999" step="any" value="1"></label><label id="objDirectionWrap" hidden>Winning means<select id="objDirection"><option value="higher">More is better</option><option value="lower">Fewer is better</option></select></label><label>Unit<select id="objUnit"><option value="count">Count</option><option value="points">Points</option><option value="percentage">Percentage · manual made/missed</option></select></label></div><p id="objComparisonHint" class="field-note" hidden>Win the battle compares both teams. Choose another goal to select a player.</p><p class="field-note">Automatic goals use recorded plays from the whole game, including plays saved before you added the goal. Manual goals begin with your first objective tap. Up to 12 total goals; hiding retains history.</p><div class="form-footer"><button class="primary" type="submit">Add objective</button></div></form></details>`;}
export function bindBuilder(game,onAdd){
 const $=id=>document.getElementById(id),form=$('objectiveForm');if(!form)return;
 let rosterKey='';
 const update=()=>{$('objTarget').max=$('objUnit').value==='percentage'?'100':'9999';const comparison=$('objGoal').value==='comparison',player=!comparison&&$('objWho').value.endsWith('_player');$('objWhoWrap').hidden=comparison;$('objPlayerWrap').hidden=!player;$('objTargetWrap').hidden=$('objGoal').value==='track';$('objDirectionWrap').hidden=!comparison;$('objComparisonHint').hidden=!comparison;$('objCustomWrap').hidden=$('objMetric').value!=='custom';const roster=($('objWho').value==='opponent_player'?game.opponentRoster:game.ourRoster)||[],key=$('objWho').value+JSON.stringify(roster);if(key!==rosterKey){rosterKey=key;$('objRosterSelect').innerHTML='<option value="">Choose a player</option>'+roster.map(p=>`<option value="${esc(p.jersey)}">${esc(C.playerLabel(game,$('objWho').value==='opponent_player'?'opponent':'us',p.jersey))}</option>`).join('')+'<option value="__manual">Enter another jersey number</option>';$('objPlayer').value='';}const manual=!roster.length||$('objRosterSelect').value==='__manual';$('objRosterWrap').hidden=!roster.length;$('objRosterEmpty').hidden=!!roster.length;$('objManualWrap').hidden=!manual;$('objRosterSelect').required=player&&roster.length>0;$('objPlayer').required=player&&manual;};
 ['objGoal','objWho','objMetric','objUnit','objRosterSelect'].forEach(id=>$(id).onchange=()=>{if(id==='objMetric')$('objUnit').value=['points','transition_points'].includes($('objMetric').value)?'points':'count';update();});
 $('objUnit').value='points';update();
 form.onsubmit=async e=>{e.preventDefault();if(e.submitter.disabled)return;e.submitter.disabled=true;try{const metric=$('objMetric').value,jersey=$('objManualWrap').hidden?$('objRosterSelect').value:$('objPlayer').value.trim(),subject=$('objGoal').value==='comparison'?'both_teams':$('objWho').value,roster=subject==='opponent_player'?game.opponentRoster:game.ourRoster,p=(roster||[]).find(p=>p.jersey===jersey),label=metric==='custom'?$('objCustom').value.trim():metrics.find(m=>m[0]===metric)[1];await onAdd({metric,label,categoryKey:metric==='custom'?'custom_'+label.toLowerCase().replace(/[^a-z0-9]+/g,'_'):metric==='points'&&subject.endsWith('_player')?'featured_player_points':metric,subject,jersey:subject.endsWith('_player')?jersey:'',playerLabel:subject.endsWith('_player')?(p?.name||''):'',goalType:$('objGoal').value,target:$('objGoal').value==='track'?0:Number($('objTarget').value),direction:$('objDirection').value,unit:$('objUnit').value});}finally{if(e.submitter.isConnected)e.submitter.disabled=false;}};
}
